section.code:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://faion.net/schemas/websocket-design.json",
  "type": "object",
  "title": "WebSocket design decision record",
  "required": [
    "envelope_version",
    "heartbeat_seconds",
    "reconnect",
    "fanout"
  ],
  "additionalProperties": false,
  "properties": {
    "envelope_version": {
      "type": "integer",
      "minimum": 1
    },
    "heartbeat_seconds": {
      "type": "integer",
      "minimum": 5,
      "maximum": 60
    },
    "reconnect": {
      "type": "object",
      "required": [
        "strategy",
        "cap_ms",
        "max_attempts"
      ],
      "properties": {
        "strategy": {
          "const": "full_jitter_exponential"
        },
        "cap_ms": {
          "type": "integer",
          "minimum": 1000,
          "maximum": 60000
        },
        "max_attempts": {
          "type": "integer",
          "minimum": 3,
          "maximum": 20
        }
      }
    },
    "fanout": {
      "enum": [
        "redis_pubsub",
        "nats",
        "kafka"
      ]
    },
    "auth_method": {
      "enum": [
        "ticket",
        "signed_cookie"
      ]
    },
    "auth_ttl_seconds": {
      "type": "integer",
      "minimum": 30,
      "maximum": 300
    },
    "send_queue_cap": {
      "type": "integer",
      "minimum": 1,
      "maximum": 1000
    },
    "send_queue_shed_policy": {
      "enum": [
        "drop_oldest",
        "drop_newest",
        "close_1008"
      ]
    },
    "message_schemas": {
      "type": "object",
      "description": "One JSON schema per message type (rule schema-validated-per-type)."
    },
    "close_codes": {
      "type": "array",
      "items": {
        "type": "integer"
      },
      "description": "RFC 6455 codes this service emits (rule close-code-truthful)."
    }
  }
}
